import { Footer } from "@/components/shared/Footer";
import { TrustBar } from "@/components/shared/TrustBar";
import { BenefitsGrid } from "@/components/shared/BenefitsGrid";
import { IngredientModule } from "@/components/shared/IngredientModule";
import { ReviewsSection } from "@/components/shared/ReviewDistribution";
import { FAQAccordion } from "@/components/shared/FAQAccordion";
import { CTABlock } from "@/components/shared/CTABlock";
import { CartDrawer } from "@/components/shared/CartDrawer";
import { StickyAddToCart } from "@/components/shared/StickyAddToCart";
import { ExitIntent } from "@/components/shared/ExitIntent";
import { SubscribeToggle } from "@/components/shared/SubscribeToggle";
import { BundleSelector } from "@/components/shared/BundleSelector";
import { PriceLine } from "@/components/shared/PriceLine";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { heroCopy } from "@/data/hero-copy";
import { useCart } from "@/components/shared/cart-context";
import { ShieldCheck, ArrowRight, Beaker } from "lucide-react";

function HeroSpec({ heroRef }: { heroRef: React.RefObject<HTMLElement | null> }) {
  const { openCart } = useCart();
  const c = heroCopy.v1Spec;
  return (
    <section ref={heroRef} className="theme-forest relative overflow-hidden bg-forest-950 text-cream-50">
      <div className="absolute inset-0 opacity-[0.04]" aria-hidden>
        <div className="size-full bg-[radial-gradient(circle_at_top_right,_var(--color-amber-400),_transparent_50%)]" />
      </div>
      <div className="relative mx-auto grid max-w-7xl gap-12 px-6 py-20 md:grid-cols-[1.1fr_1fr] md:gap-16 md:py-28">
        <div className="flex flex-col justify-center">
          <Badge className="w-fit gap-1.5 border-amber-400/30 bg-amber-400/10 text-amber-300 hover:bg-amber-400/20">
            <Beaker className="size-3" />
            {c.eyebrow}
          </Badge>
          <h1 className="mt-6 font-display text-5xl font-semibold leading-[1.05] tracking-tight md:text-6xl lg:text-7xl">
            {c.headline}
          </h1>
          <p className="mt-6 max-w-xl text-base leading-relaxed text-cream-300 md:text-lg">
            {c.subhead}
          </p>

          <div className="mt-10 grid grid-cols-3 gap-6 border-y border-white/10 py-6">
            {c.metricStrip.map((m) => (
              <div key={m.label}>
                <p className="font-display text-3xl font-semibold tabular-nums text-amber-400 md:text-4xl">
                  {m.value}
                </p>
                <p className="mt-1 font-mono text-[11px] uppercase tracking-wider text-cream-400">
                  {m.label}
                </p>
              </div>
            ))}
          </div>

          <div className="mt-8 flex flex-col gap-3 sm:flex-row">
            <Button
              onClick={openCart}
              size="lg"
              className="gap-2 bg-amber-500 text-forest-950 hover:bg-amber-400"
            >
              {c.primaryCTA}
              <ArrowRight className="size-4" />
            </Button>
            <Button
              size="lg"
              variant="outline"
              className="border-cream-50/30 bg-transparent text-cream-50 hover:bg-cream-50/10"
            >
              {c.secondaryCTA}
            </Button>
          </div>
        </div>

        <aside className="rounded-2xl border border-white/10 bg-forest-900/60 p-6 backdrop-blur-sm md:p-8">
          <div className="flex items-center justify-between">
            <p className="font-mono text-[10px] uppercase tracking-wider text-amber-300">
              Supplement facts
            </p>
            <span className="rounded-full bg-amber-400/10 px-2 py-0.5 font-mono text-[10px] uppercase tracking-wider text-amber-300">
              Per 2 caps
            </span>
          </div>
          <h3 className="mt-2 font-display text-2xl font-semibold tracking-tight text-cream-50">
            Vela Focus Formula
          </h3>
          <table className="mt-6 w-full border-collapse text-sm">
            <tbody>
              {[
                ["Citicoline (Cognizin®)", "500 mg"],
                ["Bacopa Monnieri 45%", "300 mg"],
                ["L-Theanine", "200 mg"],
                ["Lion's Mane 30%", "500 mg"],
                ["Rhodiola Rosea 3:1", "200 mg"],
              ].map(([name, dose]) => (
                <tr key={name} className="border-b border-white/10 last:border-b-0">
                  <td className="py-3 text-cream-200">{name}</td>
                  <td className="py-3 text-right font-mono text-amber-300 tabular-nums">{dose}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <div className="mt-6 space-y-4">
            <SubscribeToggle />
            <BundleSelector />
            <PriceLine />
            <Button
              onClick={openCart}
              className="w-full gap-2 bg-forest-50 text-forest-950 hover:bg-cream-50"
              size="lg"
            >
              <ShieldCheck className="size-4" />
              Add to cart
            </Button>
          </div>
        </aside>
      </div>
    </section>
  );
}

export default function Variant1Spec() {
  const heroRef = useRef<HTMLElement | null>(null);
  return (
    <CartProvider>
      <div className="min-h-screen bg-cream-50">
        <Nav variant="forest" />
        <main>
          <HeroSpec heroRef={heroRef} />
          <TrustBar />
          <BenefitsGrid />
          <IngredientModule />
          <ReviewsSection />
          <FAQAccordion />
          <CTABlock variant="primary" theme="forest" />
        </main>
        <Footer />
        <StickyAddToCart heroRef={heroRef} />
        <CartDrawer />
        <ExitIntent />
      </div>
    </CartProvider>
  );
}

