import { heroCopy } from "@/data/hero-copy";
import { ArrowRight, Star } from "lucide-react";

function HeroLifestyle({ heroRef }: { heroRef: React.RefObject<HTMLElement | null> }) {
  const { openCart } = useCart();
  const c = heroCopy.v2Lifestyle;
  return (
    <section ref={heroRef} className="relative overflow-hidden">
      <div
        className="absolute inset-0 -z-10"
        style={{
          background:
            "radial-gradient(circle at 30% 20%, var(--color-amber-200) 0%, transparent 35%), radial-gradient(circle at 80% 70%, var(--color-forest-200) 0%, transparent 45%), var(--color-cream-100)",
        }}
        aria-hidden
      />
      <div className="mx-auto grid max-w-7xl gap-10 px-6 py-24 md:grid-cols-[1.2fr_1fr] md:py-32">
        <div className="flex flex-col justify-center">
          <Badge className="w-fit gap-1.5 border-forest-200 bg-cream-50 text-forest-800 hover:bg-cream-100">
            {c.eyebrow}
          </Badge>
          <h1 className="mt-6 font-display text-6xl font-semibold leading-[1.02] tracking-tight text-forest-950 md:text-7xl lg:text-8xl">
            {c.headline}
          </h1>
          <p className="mt-7 max-w-xl text-lg leading-relaxed text-ink-700">
            {c.subhead}
          </p>

          <div className="mt-10 flex flex-col gap-3 sm:flex-row">
            <Button
              onClick={openCart}
              size="lg"
              className="gap-2 bg-forest-800 text-cream-50 hover:bg-forest-900"
            >
              {c.primaryCTA}
              <ArrowRight className="size-4" />
            </Button>
            <Button size="lg" variant="ghost" className="text-forest-800 hover:bg-cream-50">
              {c.secondaryCTA}
            </Button>
          </div>

          <div className="mt-10 flex flex-wrap items-center gap-6 border-t border-cream-300 pt-6">
            <div className="flex items-center gap-2">
              <div className="flex gap-0.5">
                {[1, 2, 3, 4, 5].map((n) => (
                  <Star key={n} className="size-4 fill-amber-500 text-amber-500" />
                ))}
              </div>
              <span className="font-mono text-xs text-ink-600">4.7 · 847 reviews</span>
            </div>
            <p className="text-xs text-ink-600">{c.socialProof}</p>
          </div>
        </div>

        <div className="relative">
          <div className="relative aspect-[3/4] overflow-hidden rounded-3xl bg-gradient-to-br from-forest-800 via-forest-700 to-forest-900 shadow-xl">
            <div
              className="absolute inset-0 opacity-30"
              style={{
                background:
                  "radial-gradient(circle at 30% 20%, var(--color-amber-400) 0%, transparent 60%)",
              }}
            />
            <div className="absolute inset-0 flex items-center justify-center">
              <div className="flex flex-col items-center gap-3">
                <div className="flex size-32 items-center justify-center rounded-full border-4 border-amber-400/50 bg-cream-50/10 backdrop-blur-md">
                  <span className="font-display text-6xl font-semibold text-amber-400">V</span>
                </div>
                <span className="font-mono text-xs uppercase tracking-[0.3em] text-cream-200">
                  Vela · 60ct
                </span>
              </div>
            </div>
            <div className="absolute bottom-6 left-6 right-6 flex items-center justify-between">
              <span className="rounded-full bg-cream-50/15 px-3 py-1.5 font-mono text-[10px] uppercase tracking-wider text-cream-50 backdrop-blur-sm">
                30-day supply
              </span>
              <span className="rounded-full bg-amber-400 px-3 py-1.5 font-mono text-[10px] uppercase tracking-wider text-forest-950">
                NSF Certified
              </span>
            </div>
          </div>
          <div className="absolute -left-6 top-12 -z-10 size-20 rounded-full bg-amber-300/40 blur-2xl" />
          <div className="absolute -right-4 bottom-20 -z-10 size-32 rounded-full bg-forest-300/40 blur-3xl" />
        </div>
      </div>
    </section>
  );
}

export default function Variant2Lifestyle() {
  const heroRef = useRef<HTMLElement | null>(null);
  return (
    <CartProvider>
      <div className="min-h-screen bg-cream-50">
        <Nav />
        <main>
          <HeroLifestyle heroRef={heroRef} />
          <PressStrip />
          <BenefitsGrid />
          <TrustBar />
          <IngredientModule />
          <ReviewsSection />
          <FAQAccordion />
          <CTABlock variant="subscription" />
        </main>
        <Footer />
        <StickyAddToCart heroRef={heroRef} />
        <CartDrawer />
        <ExitIntent />
      </div>
    </CartProvider>
  );
}

