                size="lg"
                className="gap-2 bg-forest-800 text-cream-50 hover:bg-forest-900"
              >
                {c.primaryCTA}
                <ArrowRight className="size-4" />
              </Button>
              <Button size="lg" variant="outline" className="gap-2 border-forest-800 text-forest-800 hover:bg-cream-100">
                <Play className="size-4 fill-current" />
                {c.secondaryCTA}
              </Button>
            </div>
          </div>

          <div className="relative">
            <div className="relative aspect-[4/5] overflow-hidden rounded-3xl bg-gradient-to-br from-forest-900 via-forest-800 to-amber-900 shadow-xl">
