                  aria-label="Play founder story"
                >
                  <Play className="size-7 fill-cream-50 text-cream-50" />
                </button>
              </div>

              <div className="absolute bottom-6 left-6 right-6 flex items-end justify-between gap-3">
                <div className="space-y-1">
                  <p className="font-mono text-[10px] uppercase tracking-[0.3em] text-cream-300">
                    Studio dispatch · 02:34
                  </p>
                  <p className="font-display text-xl font-semibold leading-tight text-cream-50">
                    "The spreadsheet became a bottle."
                  </p>
                </div>
                <span className="rounded-full bg-cream-50/15 px-2.5 py-1 font-mono text-[10px] uppercase tracking-wider text-cream-50 backdrop-blur-sm">
                  Live
                </span>
              </div>

              <div className="absolute right-6 top-6 flex flex-col gap-1.5">
                {[60, 90, 45, 75].map((w, i) => (
                  <div key={i} className="h-0.5 w-12 bg-cream-50/20">
                    <div
                      className="h-full bg-amber-400/80 transition-[width] duration-[var(--duration-slow)]"
                      style={{ width: `${w}%` }}
                    />
                  </div>
                ))}
              </div>
            </div>
            <div className="absolute -bottom-4 -left-4 -z-10 size-32 rounded-full bg-amber-300/30 blur-3xl" />
          </div>
        </div>
      </div>
    </section>
  );
}

