import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { heroCopy } from "@/data/hero-copy";
import { ArrowRight, Stethoscope, FileSearch, ShieldCheck, BadgeCheck, Award } from "lucide-react";

function HeroClinical({ heroRef }: { heroRef: React.RefObject<HTMLElement | null> }) {
  const { openCart } = useCart();
  const c = heroCopy.v5Clinical;
  const certIcons = [ShieldCheck, BadgeCheck, Award];
  return (
    <section ref={heroRef} className="theme-forest relative overflow-hidden bg-forest-950 text-cream-50">
      <div
        className="absolute inset-0 opacity-[0.06]"
        style={{
          backgroundImage:
            "linear-gradient(var(--color-amber-400) 1px, transparent 1px), linear-gradient(90deg, var(--color-amber-400) 1px, transparent 1px)",
          backgroundSize: "60px 60px",
        }}
        aria-hidden
      />
      <div className="relative mx-auto max-w-7xl px-6 py-20 md:py-28">
        <div className="grid gap-12 md:grid-cols-[1fr_1.05fr] md:gap-16">
          <div className="flex flex-col justify-center">
            <Badge className="w-fit gap-1.5 border-amber-400/30 bg-amber-400/10 text-amber-300 hover:bg-amber-400/20">
              <Stethoscope className="size-3" />
              {c.eyebrow}
            </Badge>
            <h1 className="mt-6 font-display text-5xl font-semibold leading-[1.05] tracking-tight md:text-6xl lg:text-7xl">
              {c.headline}
            </h1>
            <p className="mt-6 max-w-xl text-base leading-relaxed text-cream-300 md:text-lg">
              {c.subhead}
            </p>

            <div className="mt-8 flex flex-wrap gap-2">
              {c.certBadges.map((b, i) => {
                const Icon = certIcons[i] ?? ShieldCheck;
                return (
                  <span
                    key={b}
