import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import { Button } from "@/components/ui/button";
import { pageCopy } from "@/data/page-copy";
import { useState } from "react";

export function FAQAccordion() {
  const { faq } = pageCopy;
  const [openCount, setOpenCount] = useState(0);

  return (
    <section id="faq" className="bg-cream-50 py-24">
      <div className="mx-auto max-w-3xl px-6">
        <div className="mb-12 text-center">
          <p className="font-mono text-xs uppercase tracking-wider text-amber-700">
            Questions
          </p>
          <h2 className="mt-2 font-display text-4xl font-semibold tracking-tight text-forest-950 md:text-5xl">
            What buyers ask first.
          </h2>
        </div>

        <Accordion
          type="single"
          collapsible
          onValueChange={(v) => v && setOpenCount((n) => n + 1)}
          className="overflow-hidden rounded-xl border border-cream-300 bg-cream-100"
        >
          {faq.map((q, idx) => (
            <AccordionItem
              key={q.question}
              value={`faq-${idx}`}
              className="border-cream-300 last:border-b-0"
            >
              <AccordionTrigger className="px-6 py-5 text-left text-base font-semibold text-forest-950 hover:no-underline">
                {q.question}
              </AccordionTrigger>
              <AccordionContent className="px-6 pb-5 text-sm leading-relaxed text-ink-700">
                {q.answer}
              </AccordionContent>
            </AccordionItem>
          ))}
        </Accordion>

        {openCount >= 3 && (
          <div className="mt-6 rounded-xl border border-amber-200 bg-amber-50 p-5 text-center">
            <p className="font-display text-xl font-semibold text-forest-950">
              Still considering?
            </p>
            <p className="mt-1 text-sm text-ink-700">
              Read the full label before you decide.
            </p>
            <Button variant="outline" className="mt-4 border-forest-800 text-forest-800 hover:bg-forest-50">
              View full label
            </Button>
          </div>
        )}
      </div>
    </section>
  );
}

import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useCart } from "@/components/shared/cart-context";
import type { PurchaseType } from "@/lib/types";
import { Check } from "lucide-react";

export function SubscribeToggle() {
  const { purchaseType, setPurchaseType } = useCart();
  return (
    <div className="space-y-3">
      <Tabs
        value={purchaseType}
        onValueChange={(v) => setPurchaseType(v as PurchaseType)}
      >
        <TabsList className="grid w-full grid-cols-2 bg-cream-200 p-1">
          <TabsTrigger
            value="subscribe"
            className="data-[state=active]:bg-forest-800 data-[state=active]:text-cream-50"
          >
            Subscribe & Save 15%
          </TabsTrigger>
          <TabsTrigger
            value="one-time"
            className="data-[state=active]:bg-forest-800 data-[state=active]:text-cream-50"
          >
            One-time
          </TabsTrigger>
        </TabsList>
      </Tabs>
      {purchaseType === "subscribe" && (
        <ul className="space-y-1.5 text-sm text-ink-600">
          <li className="flex items-center gap-2">
            <Check className="size-3.5 text-forest-700" />
            $67/month — $2.23 per day
          </li>
          <li className="flex items-center gap-2">
            <Check className="size-3.5 text-forest-700" />
            Cancel or pause anytime. No retention emails.
          </li>
          <li className="flex items-center gap-2">
            <Check className="size-3.5 text-forest-700" />
            Free shipping on every order.
          </li>
        </ul>
      )}
    </div>
  );
}

