function renderInRouter(ui: React.ReactElement, path = "/") {
  return render(<MemoryRouter initialEntries={[path]}>{ui}</MemoryRouter>);
}

function CartHarness({ children }: { children: React.ReactNode }) {
  return (
    <CartProvider>
      <MemoryRouter>{children}</MemoryRouter>
    </CartProvider>
  );
}

// ── 1. Route renders ──────────────────────────────────────────────────────────

describe("Route smoke — each route mounts without throwing", () => {
  const cases = [
    { path: "/", Component: Index, pattern: /one brand.*five conversion/i },
    { path: "/variant-1", Component: Variant1Spec, pattern: /five actives/i },
    { path: "/variant-2", Component: Variant2Lifestyle, pattern: /think clearly/i },
    { path: "/variant-3", Component: Variant3Split, pattern: /no proprietary blends/i },
    { path: "/variant-4", Component: Variant4Founder, pattern: /refused to swallow/i },
    { path: "/variant-5", Component: Variant5Clinical, pattern: /twelve weeks/i },
  ] as const;

  cases.forEach(({ path, Component, pattern }) => {
    it(`${path} renders recognisable h1`, () => {
      // Hypothesis: each route mounts and exposes its h1 without crashing.
      renderInRouter(<Component />, path);
      expect(
        screen.getByRole("heading", { level: 1, name: pattern }),
      ).toBeInTheDocument();
    });
  });
});

