it("Subscribe → one-time: per-bottle price changes from $67 to $79", async () => {
  // Hypothesis: switching purchase type via Tabs updates displayed price.
  render(
    <CartHarness>
      <SubscribeToggle />
      <BundleSelector />
    </CartHarness>,
  );
  // Default is subscribe — $67.00/bottle visible
  expect(await screen.findByText(/\$67\.00\/bottle/i)).toBeInTheDocument();
  // Switch to one-time
  fireEvent.click(screen.getByRole("tab", { name: /one-time/i }));
  await waitFor(() =>
    expect(screen.getByText(/\$79\.00\/bottle/i)).toBeInTheDocument(),
  );
});

// ── 3. Bundle selector 2-pack ─────────────────────────────────────────────────

it("BundleSelector 2-pack: per-bottle price becomes $64.32 (subscribe)", async () => {
  // Hypothesis: selecting 2-Bottles recomputes unit price = $67 * 1.92 / 2 = $64.32.
  render(
    <CartHarness>
      <BundleSelector />
    </CartHarness>,
  );
  fireEvent.click(screen.getByRole("button", { name: /2 bottles/i }));
  await waitFor(() =>
    expect(screen.getByText(/\$64\.32\/bottle/i)).toBeInTheDocument(),
  );
});

// ── 4. Cart drawer ────────────────────────────────────────────────────────────

it("Clicking 'Add to cart' opens CartDrawer with 'Your cart' heading", async () => {
  // Hypothesis: the Add-to-cart CTA inside HeroSpec triggers the Sheet drawer.
  renderInRouter(<Variant1Spec />, "/variant-1");
  const addButtons = screen.getAllByRole("button", { name: /add to cart/i });
  const primaryAdd = addButtons[0];
  if (!primaryAdd) throw new Error("No add-to-cart button found");
  fireEvent.click(primaryAdd);
  await waitFor(() =>
    expect(screen.getByText("Your cart")).toBeInTheDocument(),
  );
});

// ── 5. FAQ third-open CTA ─────────────────────────────────────────────────────

it("FAQ: after 3 distinct item opens, 'Still considering?' CTA appears", async () => {
  // Hypothesis: onValueChange increments openCount; 3 opens triggers the soft CTA.
  render(
    <CartHarness>
      <FAQAccordion />
    </CartHarness>,
  );
  // Accordion triggers are rendered as buttons by Base UI
  const triggers = screen.getAllByRole("button");
  const faqTriggers = triggers.filter((_, i) => i < 3);
  for (const trigger of faqTriggers) {
    fireEvent.click(trigger);
  }
  await waitFor(() =>
    expect(screen.getByText(/still considering\?/i)).toBeInTheDocument(),
  );
});

// ── 6. ExitIntent suppressed on mobile ───────────────────────────────────────

it("ExitIntent: dialog does NOT open when viewport is <768px (mobile)", async () => {
  // Hypothesis: matchMedia check blocks the mouseleave listener on mobile.
  const mockMatchMedia = (query: string) => ({
    matches: query === "(max-width: 768px)",
    media: query,
    onchange: null,
    addListener: vi.fn(),
    removeListener: vi.fn(),
    addEventListener: vi.fn(),
    removeEventListener: vi.fn(),
    dispatchEvent: vi.fn(),
  });
  Object.defineProperty(window, "matchMedia", {
    writable: true,
    value: mockMatchMedia,
  });
  sessionStorage.removeItem("vela-exit-intent-shown");

  render(
    <CartHarness>
      <ExitIntent />
    </CartHarness>,
  );
  // Simulate cursor leaving viewport to top
  fireEvent(
    document,
    new MouseEvent("mouseleave", { bubbles: true, clientY: 0 }),
  );
  // Dialog must not appear
  expect(screen.queryByText(/one more thing/i)).not.toBeInTheDocument();
});

// Reset matchMedia after each test that mocks it
beforeEach(() => {
  Object.defineProperty(window, "matchMedia", {
    writable: true,
    value: (query: string) => ({
      matches: false,
      media: query,
      onchange: null,
      addListener: vi.fn(),
      removeListener: vi.fn(),
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      dispatchEvent: vi.fn(),
    }),
  });
});

